    animation: sp-spin 0.8s linear infinite;
  }

  @keyframes sp-fadein { from { opacity: 0; transform: translateY(-6px); } to { opacity: 1; transform: translateY(0); } }
  @keyframes sp-spin   { to { transform: rotate(360deg); } }
`;
